  return p.price - pct(p.price, off)
}

/// The value of the stock of a product.
pub fn stock_value(p: Product) -> Int {
  return p.price * p.stock
}

/// The value of all the stock.
pub fn catalog_value(ps: List[Product]) -> Int {
  return ps.map(fn(p) => stock_value(p)).sum()
}

/// The average price, 0 for no products.
pub fn average_price(ps: List[Product]) -> Int {
  return avg(ps.map(fn(p) => p.price).sum(), ps.len())
}

