files.money.klar:
use std.math.{floor_div}

/// Money as digits, from cents: 1250 is "12.50".
pub fn plain(cents: Int) -> Str {
  let whole = cents.abs() / 100
  let part = (cents.abs() % 100).to_str().pad_left(2, "0")
  let sign = match cents < 0 {
    true => "-",
    false => "",
  }
  return "{sign}{whole}.{part}"
}

/// Money as text, from cents: "$12.50".
pub fn fmt(cents: Int) -> Str {
  return "${plain(cents)}"
}

/// An amount times a rate, rounded half up.
pub fn pct(cents: Int, rate: Float) -> Int {
  return (cents.to_float() * rate + 0.5).floor()
}

/// An average of an amount over n items, rounded half up; 0 for no items.
pub fn avg(total: Int, n: Int) -> Int {
  if n <= 0 {
    return 0
  }
  return floor_div(2 * total + n, 2 * n)
}

